const json = require('json-stringify');

// Definimos a função principal que recebe o texto como entrada
function main(text) {
    // Extraímos o texto e o formato de saída do objeto de entrada
    const text = text.trim();
    const outputFormat = text.split(' ')[1];

    // Verificamos se o formato de saída é válido
    if (!outputFormat) {
        return {
            success: false,
            message: 'Formato de saída inválido.'
        };
    }

    // Criamos um novo objeto JSON com o texto e o formato de saída
    const output = {
        text: text,
        outputFormat: outputFormat
    };

    // Retornamos o objeto JSON formatado
    return json.stringify(output);
}

// Exportamos a função para poder utilizá-la em outros arquivos
module.exports = main;
```

### Explicando o Código Passo a Passo

#### Importação da Biblioteca JSON

Primeiro, importamos a biblioteca `json-stringify` que nos permite converter facilmente objetos JavaScript em strings JSON. Isso é útil quando queremos salvar ou transmitir dados estruturados.

```javascript
const json = require('json-stringify');
```

#### Função Principal `main()`

Esta função é responsável por receber o texto e o formato de saída como argumentos e retornar um objeto JSON contendo ambos.

```javascript
function main(text) {
    // ...
}
```

##### Tratamento de Entrada

Usamos `.trim()` para remover espaços em branco desnecessários no início e fim do texto.

```javascript
const text = text.trim();
```

##### Extração do Formato de Saída

Dividimos o texto em duas partes usando `split(' ')`. A primeira parte é o texto original, enquanto a segunda parte é o formato de saída.

```javascript
const outputFormat = text.split(' ')[1];
```

##### Validação do Formato de Saída

Verificamos se o formato de saída foi fornecido corretamente. Caso contrário, retornamos um objeto indicando que o formato é inválido.

```javascript
if (!outputFormat) {
    return {
        success: false,
        message: 'Formato de saída inválido.'
    };
}
```

##### Criação do Objeto de Saída

Criamos um novo objeto JSON contendo o texto e o formato de saída.

```javascript
const output = {
    text: text,
    outputFormat: outputFormat
};
```

##### Serialização do Objeto

Finalmente, usamos `json.stringify()` para serializar o objeto em uma string JSON e retornamos esse valor.

```javascript
return json.stringify(output);
```

#### Exportação da Função

Para que outras partes do nosso programa possam utilizar esta função, exportamos ela usando `module.exports`.

```javascript
module.exports = main;
